CREATE TABLE advanced_consent (
    tenant_id TEXT NOT NULL, scope TEXT NOT NULL, version TEXT NOT NULL,
    accepted_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
    PRIMARY KEY (tenant_id, scope)
  );

CREATE TABLE app_leases (
      name TEXT PRIMARY KEY,
      owner TEXT NOT NULL,
      expires_at BIGINT NOT NULL
    , generation BIGINT NOT NULL DEFAULT 0);

CREATE TABLE autopilot_audit (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      lead_id TEXT,
      message_id TEXT,
      action TEXT NOT NULL,
      detail TEXT CHECK (detail IS NULL OR char_length(detail) <= 200),
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE autopilot_settings (
      tenant_id TEXT PRIMARY KEY,
      enabled BIGINT NOT NULL DEFAULT 0,
      paused BIGINT NOT NULL DEFAULT 0,
      pause_reason TEXT CHECK (pause_reason IS NULL OR char_length(pause_reason) <= 100),
      consent_version TEXT,
      consent_at BIGINT,
      daily_cap BIGINT NOT NULL DEFAULT 20 CHECK (daily_cap BETWEEN 1 AND 50)
    , followups_enabled BIGINT NOT NULL DEFAULT 0);

CREATE TABLE autopilot_work (
      message_id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      lead_id TEXT NOT NULL,
      reason TEXT NOT NULL CHECK (char_length(reason) <= 40),
      next_at BIGINT,
      authority TEXT NOT NULL,
      attempts BIGINT NOT NULL DEFAULT 0,
      claimed_at BIGINT,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE calcom_bookings (
      tenant_id      TEXT NOT NULL,
      booking_uid    TEXT NOT NULL,
      attendee_email TEXT NOT NULL,
      attendee_name  TEXT,
      lead_id        TEXT,
      created_at     BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, booking_uid)
    );

CREATE TABLE calcom_hooks (
      tenant_id  TEXT PRIMARY KEY,
      secret     TEXT NOT NULL,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE company_events (
      id                 TEXT PRIMARY KEY,
      tenant_id          TEXT NOT NULL,
      company_key        TEXT NOT NULL CHECK (char_length(company_key) <= 254),
      company_name       TEXT CHECK (company_name IS NULL OR char_length(company_name) <= 200),
      scope              TEXT NOT NULL CHECK (scope IN ('account','market')),
      lead_id            TEXT,
      event_type         TEXT NOT NULL,
      summary            TEXT NOT NULL CHECK (char_length(summary) <= 300),
      detail             TEXT,
      source_url         TEXT NOT NULL CHECK (char_length(source_url) <= 500 AND lower(source_url) LIKE lower('http%')),
      source_published_at TEXT CHECK (source_published_at IS NULL OR char_length(source_published_at) = 10),
      retrieved_at       BIGINT NOT NULL,
      first_seen_at      BIGINT NOT NULL,
      last_seen_at       BIGINT NOT NULL,
      confidence         BIGINT,
      UNIQUE (tenant_id, company_key, event_type, source_url)
    );

CREATE TABLE connector_audit (
      id         TEXT PRIMARY KEY,
      tenant_id  TEXT NOT NULL,
      connector  TEXT NOT NULL,
      scan_job_id TEXT,
      lookup     TEXT NOT NULL CHECK (char_length(lookup) <= 200),
      status     TEXT NOT NULL,
      results    BIGINT NOT NULL DEFAULT 0,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    , insert_seq BIGINT DEFAULT nextval('connector_audit_insert_seq_seq'));

CREATE TABLE consent_ledger (
      id           TEXT PRIMARY KEY,
      tenant_id    TEXT NOT NULL,
      contact      TEXT NOT NULL,
      channel      TEXT NOT NULL CHECK (channel IN ('email','phone')),
      scope        TEXT NOT NULL CHECK (char_length(scope) <= 40),
      basis        TEXT NOT NULL CHECK (char_length(basis) <= 40),
      evidence_ref TEXT NOT NULL CHECK (char_length(evidence_ref) <= 200),
      granted_at   BIGINT NOT NULL,
      expires_at   BIGINT NOT NULL,
      revoked_at   BIGINT,
      revoke_reason TEXT CHECK (revoke_reason IS NULL OR char_length(revoke_reason) <= 60)
    );

CREATE TABLE crm_push_claims (
      tenant_id   TEXT NOT NULL,
      destination TEXT NOT NULL,
      lead_id     TEXT NOT NULL,
      status      TEXT NOT NULL CHECK (status IN ('pending', 'ok', 'failed', 'uncertain', 'resolved_created', 'resolved_not_created')),
      external_id TEXT,
      attempt_id  TEXT NOT NULL,
      claimed_at  BIGINT NOT NULL,
      updated_at  BIGINT NOT NULL,
      PRIMARY KEY (tenant_id, destination, lead_id)
    );

CREATE TABLE csv_batches (
      id         TEXT PRIMARY KEY,
      user_id    TEXT NOT NULL,
      total      BIGINT NOT NULL,
      note       TEXT,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE email_candidates (
      tenant_id TEXT NOT NULL, lead_id TEXT NOT NULL, person TEXT NOT NULL CHECK (char_length(person) <= 120),
      address TEXT NOT NULL CHECK (char_length(address) <= 254), format TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'unverified' CHECK (status IN ('unverified')),
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)), PRIMARY KEY (lead_id, address));

CREATE TABLE email_patterns (
      tenant_id TEXT NOT NULL, lead_id TEXT NOT NULL, site TEXT NOT NULL, format TEXT NOT NULL, support BIGINT NOT NULL,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)), PRIMARY KEY (lead_id, site));

CREATE TABLE email_tokens (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    purpose TEXT NOT NULL CHECK (purpose IN ('verify', 'reset', 'change')),
    email TEXT NOT NULL CHECK (char_length(email) <= 254),
    token_hash TEXT NOT NULL UNIQUE,
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    used_at BIGINT
  );

CREATE TABLE evidence_purge_audit (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  operator TEXT NOT NULL CHECK (char_length(operator) BETWEEN 2 AND 120),
  reason TEXT NOT NULL CHECK (char_length(reason) BETWEEN 10 AND 500),
  copies_deleted BIGINT NOT NULL,
  bytes_deleted BIGINT NOT NULL,
  leads_unlinked BIGINT NOT NULL,
  created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
);

CREATE TABLE evidence_purge_gate (tenant_id TEXT PRIMARY KEY);

CREATE TABLE followup_messages (
      tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, step BIGINT NOT NULL, status TEXT NOT NULL CHECK (status IN ('sending','sent','uncertain')),
      gmail_id TEXT, created_at BIGINT NOT NULL, PRIMARY KEY (tenant_id, thread_id, step)
    );

CREATE TABLE followup_threads (
      tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, lead_id TEXT NOT NULL, to_email TEXT NOT NULL, root_message_id TEXT NOT NULL,
      last_activity_at BIGINT NOT NULL, last_lead_reply_at BIGINT, followups_sent BIGINT NOT NULL DEFAULT 0, last_followup_at BIGINT,
      stopped TEXT CHECK (stopped IS NULL OR char_length(stopped) <= 40),
      PRIMARY KEY (tenant_id, thread_id)
    );

CREATE TABLE gmail_accounts (
      tenant_id    TEXT PRIMARY KEY,
      email        TEXT NOT NULL,
      refresh_ct   TEXT NOT NULL,
      status       TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','needs_reconnect')),
      connected_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    , read_granted BIGINT NOT NULL DEFAULT 0);

CREATE TABLE hiring_feed_crawl (
    lead_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, company_key TEXT NOT NULL, status TEXT NOT NULL, started_at BIGINT NOT NULL, finished_at BIGINT, claim TEXT
  );

CREATE TABLE inbound_messages (
      gmail_id TEXT NOT NULL, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, lead_id TEXT, from_email TEXT NOT NULL,
      excerpt TEXT NOT NULL CHECK (char_length(excerpt) <= 200), classification TEXT NOT NULL, received_at BIGINT NOT NULL, outreach_message_id TEXT,
      PRIMARY KEY (tenant_id, gmail_id)
    );

CREATE TABLE inbox_thread_reads (tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, read_upto BIGINT NOT NULL, PRIMARY KEY (tenant_id, thread_id));

CREATE TABLE invitations (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    email TEXT NOT NULL CHECK (char_length(email) <= 254),
    role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'operator', 'viewer')),
    token_hash TEXT NOT NULL UNIQUE,
    invited_by TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    accepted_at BIGINT,
    accepted_by TEXT,
    revoked_at BIGINT
  );

CREATE TABLE lead_enrichments (
      id          TEXT PRIMARY KEY,
      lead_id     TEXT NOT NULL,
      tenant_id   TEXT NOT NULL,
      connector   TEXT NOT NULL,
      kind        TEXT NOT NULL,
      value       TEXT NOT NULL CHECK (char_length(value) <= 254),
      label       TEXT CHECK (label IS NULL OR char_length(label) <= 200),
      confidence  BIGINT,
      source_url  TEXT NOT NULL CHECK (char_length(source_url) <= 500 AND lower(source_url) LIKE lower('http%')),
      source_date TEXT NOT NULL CHECK (char_length(source_date) = 10),
      retrieved_at BIGINT NOT NULL, insert_seq BIGINT DEFAULT nextval('lead_enrichments_insert_seq_seq'),
      UNIQUE (lead_id, connector, kind, value)
    );

CREATE TABLE lead_evidence_copies (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  job_id TEXT NOT NULL,
  attempt BIGINT NOT NULL,
  source_url TEXT NOT NULL,
  canonical_url TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '' CHECK (octet_length(title) <= 1024),
  title_sha256 TEXT NOT NULL CHECK (char_length(title_sha256) = 64),
  sha256 TEXT NOT NULL CHECK (char_length(sha256) = 64),
  text TEXT NOT NULL,
  byte_length BIGINT NOT NULL CHECK (byte_length <= 262144),
  fetched_at BIGINT NOT NULL,
  created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
  expires_at BIGINT NOT NULL,
  UNIQUE (tenant_id, job_id, attempt, canonical_url)
);

CREATE TABLE lead_qualifications (
    tenant_id TEXT NOT NULL, lead_id TEXT NOT NULL, prompt_sha256 TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('running','done','failed')),
    vendor TEXT, model TEXT, served_model TEXT, result TEXT, usage TEXT, error TEXT, evidence TEXT,
    created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
    UNIQUE (tenant_id, lead_id, prompt_sha256));

CREATE TABLE mail_read_consent (tenant_id TEXT PRIMARY KEY, version TEXT NOT NULL, accepted_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)));

CREATE TABLE memberships (
    tenant_id TEXT NOT NULL,
    member_id TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'operator', 'viewer')),
    created_at BIGINT NOT NULL,
    added_by TEXT,
    PRIMARY KEY (tenant_id, member_id)
  );

CREATE TABLE monitors (
      id             TEXT PRIMARY KEY,
      user_id        TEXT NOT NULL,
      query          TEXT NOT NULL CHECK (char_length(query) BETWEEN 3 AND 600),
      icp            TEXT,
      sources        TEXT,
      interval_hours BIGINT NOT NULL,
      enabled        BIGINT NOT NULL DEFAULT 1,
      paused_reason  TEXT,
      last_run_at    BIGINT,
      next_run_at    BIGINT,
      created_at     BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE newsjacks (
      id         TEXT PRIMARY KEY,
      tenant_id  TEXT NOT NULL,
      url        TEXT NOT NULL CHECK (char_length(url) <= 500),
      title      TEXT,
      draft      TEXT NOT NULL,
      status     TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved')),
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE oauth_identities (
    provider TEXT NOT NULL, subject TEXT NOT NULL, user_id TEXT NOT NULL, created_at BIGINT DEFAULT (floor(extract(epoch from now()))),
    PRIMARY KEY (provider, subject)
  );

CREATE TABLE oauth_states (
      state_hash TEXT PRIMARY KEY,
      tenant_id  TEXT NOT NULL,
      verifier   TEXT NOT NULL,
      expires_at BIGINT NOT NULL
    , read_scope BIGINT NOT NULL DEFAULT 0);

CREATE TABLE organizations (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL DEFAULT '' CHECK (char_length(name) <= 150),
    kind TEXT NOT NULL CHECK (kind IN ('personal', 'team')),
    created_by TEXT NOT NULL,
    created_at BIGINT NOT NULL
  );

CREATE TABLE outreach_llm_usage (
      id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      tenant_id     TEXT NOT NULL,
      message_id    TEXT,
      purpose       TEXT NOT NULL,
      vendor        TEXT,
      requested_model TEXT,
      model         TEXT,
      request_id    TEXT,
      outcome       TEXT NOT NULL,
      input_tokens  BIGINT,
      output_tokens BIGINT,
      cache_read_input_tokens BIGINT,
      cache_creation_input_tokens BIGINT,
      created_at    BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE outreach_messages (
      id             TEXT PRIMARY KEY,
      tenant_id      TEXT NOT NULL,
      lead_id        TEXT NOT NULL,
      to_email       TEXT NOT NULL,
      subject        TEXT NOT NULL CHECK (char_length(subject) BETWEEN 1 AND 150),
      body           TEXT NOT NULL CHECK (char_length(body) BETWEEN 20 AND 3000),
      status         TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','sending','sent','skipped','uncertain')),
      approved_hash  TEXT,
      attempts       BIGINT NOT NULL DEFAULT 0,
      claimed_at     BIGINT,
      sent_at        BIGINT,
      gmail_id       TEXT,
      error          TEXT CHECK (error IS NULL OR char_length(error) <= 200),
      created_at     BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)), thread_id TEXT, test BIGINT NOT NULL DEFAULT 0, insert_seq BIGINT DEFAULT nextval('outreach_messages_insert_seq_seq'),
      UNIQUE (tenant_id, lead_id)
    );

CREATE TABLE outreach_settings (
      tenant_id      TEXT PRIMARY KEY,
      sender_name    TEXT NOT NULL CHECK (char_length(sender_name) BETWEEN 1 AND 100),
      postal_address TEXT NOT NULL CHECK (char_length(postal_address) BETWEEN 10 AND 300)
    , booking_url TEXT);

CREATE TABLE outreach_signal_context (
    message_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    lead_id TEXT NOT NULL,
    scan_job_id TEXT NOT NULL,
    signal TEXT,
    signals_json TEXT,
    signal_kind TEXT,
    source_kind TEXT,
    source_url TEXT,
    collectors_json TEXT,
    captured_at BIGINT NOT NULL
  );

CREATE TABLE play_research_sources (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, fingerprint TEXT NOT NULL,
 input_json TEXT NOT NULL, query_snapshot TEXT NOT NULL, offer_snapshot TEXT NOT NULL,
 play_created_at BIGINT NOT NULL, icp_snapshot TEXT, offer_source TEXT NOT NULL,
 source_check TEXT NOT NULL, person_check TEXT, created_at BIGINT NOT NULL,
 UNIQUE(tenant_id,job_id,fingerprint)
);

CREATE TABLE rate_limits (
      key TEXT PRIMARY KEY CHECK (char_length(key) <= 300),
      count BIGINT NOT NULL,
      reset_at BIGINT NOT NULL
    );

CREATE TABLE reopen_messages (
      tenant_id  TEXT NOT NULL,
      thread_id  TEXT NOT NULL,
      lead_id    TEXT NOT NULL,
      to_email   TEXT NOT NULL,
      body       TEXT NOT NULL CHECK (char_length(body) BETWEEN 20 AND 3000),
      status     TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','sent','skipped')),
      gmail_id   TEXT,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      sent_at    BIGINT,
      PRIMARY KEY (tenant_id, thread_id)
    );

CREATE TABLE reply_drafts (
      thread_id  TEXT PRIMARY KEY,
      tenant_id  TEXT NOT NULL,
      draft      TEXT NOT NULL,
      status     TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','edited','copied','posted')),
      updated_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE reply_queries (
      tenant_id  TEXT NOT NULL,
      query      TEXT NOT NULL,
      position   BIGINT NOT NULL,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, query)
    );

CREATE TABLE reply_threads (
      id           TEXT PRIMARY KEY,
      tenant_id    TEXT NOT NULL,
      platform     TEXT NOT NULL CHECK (platform IN ('reddit','x')),
      url          TEXT NOT NULL,
      title        TEXT NOT NULL,
      quote        TEXT NOT NULL,
      query        TEXT NOT NULL,
      date         TEXT,
      login_walled BIGINT NOT NULL DEFAULT 0,
      buyer_intent TEXT CHECK (buyer_intent IS NULL OR buyer_intent IN ('yes','no','uncertain')),
      created_at   BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      UNIQUE (tenant_id, url)
    );

CREATE TABLE scan_jobs (
      id            TEXT PRIMARY KEY,
      user_id       TEXT NOT NULL,
      status        TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','done','failed')),
      business_name TEXT NOT NULL CHECK (char_length(business_name) BETWEEN 1 AND 150),
      industry      TEXT NOT NULL CHECK (char_length(industry) BETWEEN 1 AND 100),
      location      TEXT NOT NULL CHECK (char_length(location) BETWEEN 1 AND 100),
      attempts      BIGINT NOT NULL DEFAULT 0,
      error         TEXT CHECK (error IS NULL OR char_length(error) <= 200),
      created_at    BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      claimed_at    BIGINT,
      finished_at   BIGINT
    , funded_by TEXT NOT NULL DEFAULT 'user', seller TEXT, offer TEXT CHECK (offer IS NULL OR char_length(offer) <= 150), offer_set_at BIGINT, watch_id TEXT, candidates BIGINT, needs_review BIGINT, dropped BIGINT, run_budget TEXT, estimate TEXT, spend_reserved_usd DOUBLE PRECISION, drop_reasons TEXT, verified BIGINT, query TEXT CHECK (query IS NULL OR char_length(query) <= 600), icp TEXT CHECK (icp IS NULL OR char_length(icp) <= 4000), icp_inferred BIGINT, sources TEXT CHECK (sources IS NULL OR char_length(sources) <= 2000), csv_domain TEXT CHECK (csv_domain IS NULL OR char_length(csv_domain) <= 253), batch_id TEXT, enrich_started_at BIGINT, enrich_finished_at BIGINT, insert_seq BIGINT DEFAULT nextval('scan_jobs_insert_seq_seq'));

CREATE TABLE scan_model_calls (
    tenant_id TEXT NOT NULL,
    job_id TEXT REFERENCES scan_jobs(id) ON DELETE CASCADE,
    attempt BIGINT NOT NULL,
    seq BIGINT NOT NULL,
    stage TEXT NOT NULL CHECK (char_length(stage) <= 40),
    method TEXT NOT NULL,
    model_requested TEXT CHECK (model_requested IS NULL OR char_length(model_requested) <= 100),
    model_served TEXT CHECK (model_served IS NULL OR char_length(model_served) <= 100),
    input_tokens BIGINT,
    output_tokens BIGINT,
    outcome TEXT NOT NULL,
    max_tokens BIGINT,
    prompt_chars BIGINT NOT NULL,
    recorded_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
  );

CREATE TABLE scan_run_report (
    job_id TEXT NOT NULL REFERENCES scan_jobs(id) ON DELETE CASCADE,
    attempt BIGINT NOT NULL,
    report TEXT NOT NULL CHECK (char_length(report) <= 120000),
    created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
    PRIMARY KEY (job_id, attempt)
  );

CREATE TABLE scan_source_runs (
      job_id TEXT NOT NULL REFERENCES scan_jobs(id) ON DELETE CASCADE,
      attempt BIGINT NOT NULL,
      collector TEXT NOT NULL,
      status TEXT NOT NULL,
      evidence_count BIGINT,
      candidate_count BIGINT,
      verified_count BIGINT,
      review_count BIGINT,
      inserted_count BIGINT NOT NULL,
      PRIMARY KEY (job_id, attempt, collector)
    );

CREATE TABLE scan_source_stats (
    job_id TEXT NOT NULL REFERENCES scan_jobs(id) ON DELETE CASCADE,
    attempt BIGINT NOT NULL,
    collector TEXT NOT NULL,
    queries TEXT CHECK (queries IS NULL OR char_length(queries) <= 2000),
    query_source TEXT CHECK (query_source IS NULL OR query_source IN ('model','fallback')),
    searches_attempted BIGINT,
    searches_ok BIGINT,
    searches_failed TEXT CHECK (searches_failed IS NULL OR char_length(searches_failed) <= 200),
    searches_not_attempted TEXT CHECK (searches_not_attempted IS NULL OR char_length(searches_not_attempted) <= 200),
    hits_raw BIGINT,
    hits_unique_urls BIGINT,
    hits_complete BIGINT CHECK (hits_complete IS NULL OR hits_complete IN (0,1)),
    fetch_complete BIGINT CHECK (fetch_complete IS NULL OR fetch_complete IN (0,1)),
    fetch_requested BIGINT,
    fetch_outcome TEXT CHECK (fetch_outcome IS NULL OR char_length(fetch_outcome) <= 40),
    fetch_pages_with_text BIGINT,
    per_query TEXT CHECK (per_query IS NULL OR char_length(per_query) <= 4000),
    distinct_hosts BIGINT,
    urls_not_fetched BIGINT,
    extracted_candidates BIGINT,
    model_requested TEXT CHECK (model_requested IS NULL OR char_length(model_requested) <= 100),
    model_served TEXT CHECK (model_served IS NULL OR char_length(model_served) <= 100),
    model_calls BIGINT,
    input_tokens BIGINT,
    output_tokens BIGINT,
    evidence_items BIGINT,
    evidence_with_page_text BIGINT,
    evidence_snippet_only BIGINT,
    PRIMARY KEY (job_id, attempt, collector)
  );

CREATE TABLE scheduler_progress (
      tenant_id            TEXT NOT NULL,
      kind                 TEXT NOT NULL CHECK (kind IN ('reply_sync','followups','sequences','autopilot')),
      last_attempt_at      BIGINT NOT NULL,
      last_success_at      BIGINT,
      last_error           TEXT CHECK (last_error IS NULL OR char_length(last_error) <= 200),
      last_outcome         TEXT NOT NULL DEFAULT 'success' CHECK (last_outcome IN ('success','hold','failure')),
      last_hold            TEXT CHECK (last_hold IS NULL OR char_length(last_hold) <= 40),
      consecutive_failures BIGINT NOT NULL DEFAULT 0,
      last_run_id          TEXT,
      PRIMARY KEY (tenant_id, kind)
    );

CREATE TABLE scheduler_runs (
      id                TEXT PRIMARY KEY,
      started_at        BIGINT NOT NULL,
      finished_at       BIGINT,
      status            TEXT NOT NULL CHECK (status IN ('running','ok','partial','failed','lease_lost')),
      lease_owner       TEXT NOT NULL,
      lease_generation  BIGINT NOT NULL,
      tenants_attempted BIGINT NOT NULL DEFAULT 0,
      tenants_failed    BIGINT NOT NULL DEFAULT 0,
      error             TEXT CHECK (error IS NULL OR char_length(error) <= 200)
    );

CREATE TABLE seo_audits (
    id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, domain TEXT NOT NULL,
    results TEXT NOT NULL, created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
  );

CREATE TABLE seo_briefs (
      id         TEXT PRIMARY KEY,
      tenant_id  TEXT NOT NULL,
      topic      TEXT NOT NULL CHECK (char_length(topic) BETWEEN 3 AND 300),
      brief      TEXT NOT NULL,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE seo_index_configs (
      tenant_id   TEXT PRIMARY KEY,
      domain      TEXT NOT NULL,
      next_run_at BIGINT
    );

CREATE TABLE seo_index_keywords (
      tenant_id  TEXT NOT NULL,
      keyword    TEXT NOT NULL CHECK (char_length(keyword) BETWEEN 1 AND 120),
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, keyword)
    );

CREATE TABLE seo_index_results (
      id         TEXT PRIMARY KEY,
      tenant_id  TEXT NOT NULL,
      keyword    TEXT NOT NULL,
      indexed    BIGINT NOT NULL,
      top_url    TEXT,
      checked_at BIGINT NOT NULL
    );

CREATE TABLE seo_index_runs (
      tenant_id TEXT NOT NULL,
      ran_at    BIGINT NOT NULL,
      searches  BIGINT NOT NULL
    );

CREATE TABLE sequence_settings (
      tenant_id      TEXT PRIMARY KEY,
      test_addresses TEXT NOT NULL DEFAULT '[]'
    );

CREATE TABLE sequence_steps (
      tenant_id     TEXT NOT NULL,
      sequence_id   TEXT NOT NULL,
      step          BIGINT NOT NULL CHECK (step BETWEEN 1 AND 3),
      subject       TEXT NOT NULL,
      body          TEXT NOT NULL,
      approved_hash TEXT,
      status        TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','sending','sent','uncertain')),
      gmail_id      TEXT,
      claimed_at    BIGINT,
      sent_at       BIGINT,
      created_at    BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, sequence_id, step)
    );

CREATE TABLE sequences (
      id          TEXT PRIMARY KEY,
      tenant_id   TEXT NOT NULL,
      lead_id     TEXT NOT NULL,
      message_id  TEXT NOT NULL,
      to_email    TEXT NOT NULL,
      status      TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','active','replied','done','stopped')),
      stop_reason TEXT CHECK (stop_reason IS NULL OR char_length(stop_reason) <= 40),
      created_at  BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      UNIQUE (tenant_id, lead_id)
    );

CREATE TABLE sessions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      created_at BIGINT DEFAULT (floor(extract(epoch from now()))),
      expires_at BIGINT NOT NULL
    , active_tenant_id TEXT, public_id TEXT, last_seen_at BIGINT, device TEXT, revoked_at BIGINT, revoked_by TEXT, revoke_reason TEXT, authed_at BIGINT);

CREATE TABLE source_reviews (
 id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, lead_id TEXT NOT NULL,
 input_json TEXT NOT NULL, fetch_status TEXT NOT NULL, quote_match BIGINT NOT NULL,
 company_named BIGINT NOT NULL, contact_match BIGINT NOT NULL, checked_at BIGINT NOT NULL
 );

CREATE TABLE stripe_ended_subscriptions (
      subscription_id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      ended_at BIGINT
    );

CREATE TABLE stripe_events (
      id TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      processed_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE suppressions (
      tenant_id  TEXT NOT NULL,
      email      TEXT NOT NULL,
      reason     TEXT NOT NULL CHECK (reason IN ('unsubscribe','manual','bounce')),
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, email)
    );

CREATE TABLE system_mail_outbox (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    to_email TEXT NOT NULL,
    subject TEXT NOT NULL,
    body TEXT NOT NULL,
    created_at BIGINT NOT NULL
  );

CREATE TABLE tenant_competitors (
    tenant_id TEXT NOT NULL, name TEXT NOT NULL, position BIGINT NOT NULL,
    PRIMARY KEY (tenant_id, name)
  );

CREATE TABLE tenant_connections (
      tenant_id    TEXT NOT NULL,
      name         TEXT NOT NULL CHECK (char_length(name) <= 200),
      linkedin_url TEXT NOT NULL,
      company      TEXT CHECK (company IS NULL OR char_length(company) <= 200),
      position     TEXT CHECK (position IS NULL OR char_length(position) <= 200),
      connected_on TEXT CHECK (connected_on IS NULL OR char_length(connected_on) <= 20),
      imported_at  BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, linkedin_url)
    );

CREATE TABLE tenant_connectors (
      tenant_id    TEXT NOT NULL,
      connector    TEXT NOT NULL,
      ciphertext   TEXT NOT NULL,
      last4        TEXT NOT NULL,
      enabled      BIGINT NOT NULL DEFAULT 1,
      created_at   BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, connector)
    );

CREATE TABLE tenant_llm_keys (
      tenant_id    TEXT NOT NULL,
      vendor       TEXT NOT NULL CHECK (vendor IN ('anthropic','openai')),
      ciphertext   TEXT NOT NULL,
      last4        TEXT NOT NULL,
      validated_at BIGINT NOT NULL,
      created_at   BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (tenant_id, vendor)
    );

CREATE TABLE tenant_memory (
      tenant_id   TEXT PRIMARY KEY,
      icp         TEXT NOT NULL DEFAULT '' CHECK (char_length(icp) <= 600),
      positioning TEXT NOT NULL DEFAULT '' CHECK (char_length(positioning) <= 600),
      tone        TEXT NOT NULL DEFAULT '' CHECK (char_length(tone) <= 200),
      exclusions  TEXT NOT NULL DEFAULT '[]',
      objections  TEXT NOT NULL DEFAULT '[]',
      updated_at  BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE tenant_plans (
      tenant_id TEXT PRIMARY KEY,
      plan TEXT NOT NULL DEFAULT 'free' CHECK (plan IN ('free','pro')),
      stripe_customer_id TEXT,
      stripe_subscription_id TEXT
    , stripe_event_at BIGINT, stripe_reconcile_at BIGINT, subscription_status TEXT);

CREATE TABLE tenant_spend_pools (
    tenant_id TEXT NOT NULL, period TEXT NOT NULL CHECK (char_length(period) <= 12),
    reserved_usd DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (reserved_usd >= 0), reported_usd DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (reported_usd >= 0),
    calls BIGINT NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL,
    PRIMARY KEY (tenant_id, period)
  );

CREATE TABLE tinyfish_usage (day TEXT NOT NULL, tenant_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('search','fetch')), n BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (day, tenant_id, kind));

CREATE TABLE trial_budget_lock (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id = 1), n BIGINT NOT NULL DEFAULT 0);

CREATE TABLE trial_reservations (
      id          TEXT PRIMARY KEY,
      tenant_id   TEXT NOT NULL,
      job_id      TEXT,
      reserve_usd DOUBLE PRECISION NOT NULL CHECK (reserve_usd > 0),
      day         BIGINT NOT NULL,
      created_at  BIGINT NOT NULL,
      settled_at  BIGINT,
      settled_attempt BIGINT
    );

CREATE TABLE trial_scans (
      tenant_id TEXT NOT NULL,
      job_id TEXT NOT NULL,
      ip_hash TEXT NOT NULL,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE users (
      id TEXT PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      name TEXT,
      business_name TEXT,
      sells TEXT,
      website TEXT,
      password_hash TEXT NOT NULL,
      salt TEXT NOT NULL,
      created_at BIGINT DEFAULT (floor(extract(epoch from now())))
    , buyer_profile TEXT, email_verified_at BIGINT);

CREATE TABLE warm_user_paths (
      id           TEXT PRIMARY KEY,
      tenant_id    TEXT NOT NULL,
      lead_id      TEXT NOT NULL,
      contact_url  TEXT NOT NULL,
      mutual_name  TEXT NOT NULL CHECK (char_length(mutual_name) <= 200),
      note         TEXT CHECK (note IS NULL OR char_length(note) <= 500),
      created_at   BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)), insert_seq BIGINT DEFAULT nextval('warm_user_paths_insert_seq_seq'),
      UNIQUE (tenant_id, lead_id, contact_url, mutual_name)
    );

CREATE TABLE watches (
    id          TEXT PRIMARY KEY,
    user_id     TEXT NOT NULL,
    query       TEXT NOT NULL,
    icp         TEXT NOT NULL,
    active      BIGINT NOT NULL DEFAULT 1,
    next_run_at BIGINT NOT NULL,
    last_run_at BIGINT,
    paused_reason TEXT,
    created_at  BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
  , run_budget TEXT);

CREATE TABLE work_queue (
        id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        kind TEXT NOT NULL,
        status TEXT NOT NULL,
        attempts BIGINT NOT NULL,
        max_attempts BIGINT NOT NULL,
        not_before BIGINT NOT NULL,
        created_at BIGINT NOT NULL,
        claimed_at BIGINT,
        lease_expires_at BIGINT,
        claim_token BIGINT,
        last_error TEXT,
        dedupe_key TEXT
      );

CREATE TABLE work_queue_meta (k TEXT PRIMARY KEY, v BIGINT NOT NULL);

CREATE TABLE commenter_batches (
      id         TEXT PRIMARY KEY,
      user_id    TEXT NOT NULL,
      context    TEXT NOT NULL CHECK (char_length(context) BETWEEN 1 AND 500),
      total      BIGINT NOT NULL,
      job_id     TEXT REFERENCES scan_jobs(id) ON DELETE SET NULL,
      note       TEXT,
      created_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT))
    );

CREATE TABLE csv_rows (
      id       TEXT PRIMARY KEY,
      batch_id TEXT NOT NULL REFERENCES csv_batches(id) ON DELETE CASCADE,
      domain   TEXT NOT NULL CHECK (char_length(domain) BETWEEN 1 AND 253),
      state    TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','skipped')),
      note     TEXT,
      job_id   TEXT REFERENCES scan_jobs(id) ON DELETE SET NULL
    );

CREATE TABLE leads (
      id          TEXT PRIMARY KEY,
      scan_job_id TEXT NOT NULL REFERENCES scan_jobs(id) ON DELETE CASCADE,
      name        TEXT NOT NULL DEFAULT '' CHECK (char_length(name) <= 150),
      company     TEXT NOT NULL DEFAULT '' CHECK (char_length(company) <= 150),
      contact     TEXT CHECK (contact IS NULL OR char_length(contact) <= 254),
      signal      TEXT NOT NULL CHECK (char_length(signal) BETWEEN 1 AND 500),
      source_url  TEXT NOT NULL CHECK (char_length(source_url) <= 500 AND (lower(source_url) LIKE lower('https://%') OR lower(source_url) LIKE lower('http://%'))),
      score       BIGINT NOT NULL DEFAULT 50 CHECK (score BETWEEN 0 AND 100),
      created_at  BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)), stage TEXT, watch_new BIGINT NOT NULL DEFAULT 0, evidence_excerpt TEXT CHECK (evidence_excerpt IS NULL OR char_length(evidence_excerpt) <= 400), icp_match TEXT CHECK (icp_match IS NULL OR char_length(icp_match) <= 400), event_date TEXT, date_status TEXT CHECK (date_status IS NULL OR date_status IN ('verified','unverified','undated')), retrieved_at BIGINT, confidence BIGINT CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 100), dedup_key TEXT, review_reason TEXT, evidence_origin TEXT CHECK (evidence_origin IS NULL OR evidence_origin IN ('tinyfish_copy')), own_fetch_failure TEXT, evidence_copy_sha256 TEXT, evidence_purged_at BIGINT, timing_note TEXT CHECK (timing_note IS NULL OR char_length(timing_note) <= 300), published_at TEXT, evidence_copy_id TEXT, human_confirmed_at BIGINT, human_confirmed_from TEXT, company_domain TEXT CHECK (company_domain IS NULL OR char_length(company_domain) <= 253), quarantined_at BIGINT, quarantine_reason TEXT CHECK (quarantine_reason IS NULL OR char_length(quarantine_reason) <= 300), fit BIGINT CHECK (fit IS NULL OR fit BETWEEN 0 AND 5), intent BIGINT CHECK (intent IS NULL OR intent BETWEEN 0 AND 5), action BIGINT CHECK (action IS NULL OR action BETWEEN 0 AND 5), why TEXT CHECK (why IS NULL OR char_length(why) <= 600), signals TEXT CHECK (signals IS NULL OR char_length(signals) <= 1000), seen_before BIGINT NOT NULL DEFAULT 0, signal_kind TEXT, source_kind TEXT, insert_seq BIGINT DEFAULT nextval('leads_insert_seq_seq'),
      CHECK (name <> '' OR company <> '')
    );

CREATE TABLE monitor_runs (
      id         TEXT PRIMARY KEY,
      monitor_id TEXT NOT NULL REFERENCES monitors(id) ON DELETE CASCADE,
      job_id     TEXT NOT NULL,
      ran_at     BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      processed  BIGINT NOT NULL DEFAULT 0,
      new_count  BIGINT
    );

CREATE TABLE monitor_seen (
      monitor_id TEXT NOT NULL REFERENCES monitors(id) ON DELETE CASCADE,
      dedup_key  TEXT NOT NULL,
      first_seen_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
      PRIMARY KEY (monitor_id, dedup_key)
    );

CREATE TABLE watch_seen (
    watch_id   TEXT NOT NULL REFERENCES watches(id) ON DELETE CASCADE,
    seen_key   TEXT NOT NULL,
    first_seen_at BIGINT NOT NULL DEFAULT (CAST(floor(extract(epoch from now())) AS BIGINT)),
    PRIMARY KEY (watch_id, seen_key)
  );

CREATE TABLE commenter_rows (
      id          TEXT PRIMARY KEY,
      batch_id    TEXT NOT NULL REFERENCES commenter_batches(id) ON DELETE CASCADE,
      profile_url TEXT NOT NULL CHECK (char_length(profile_url) BETWEEN 1 AND 500),
      slug        TEXT NOT NULL CHECK (char_length(slug) BETWEEN 1 AND 100),
      name        TEXT NOT NULL CHECK (char_length(name) BETWEEN 1 AND 150),
      name_source TEXT NOT NULL CHECK (name_source IN ('csv','derived')),
      title       TEXT CHECK (title IS NULL OR char_length(title) <= 150),
      company     TEXT CHECK (company IS NULL OR char_length(company) <= 150),
      lead_id     TEXT REFERENCES leads(id) ON DELETE SET NULL,
      note        TEXT
    );

CREATE TABLE lead_sources (
      lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
      collector TEXT NOT NULL,
      attempt BIGINT NOT NULL,
      PRIMARY KEY (lead_id, collector, attempt)
    );

