CREATE OR REPLACE FUNCTION dazl_guard_evidence_purge_audit_no_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (TRUE) THEN RAISE EXCEPTION 'purge audit is append-only'; END IF;
  RETURN OLD;
END $$;
DROP TRIGGER IF EXISTS evidence_purge_audit_no_delete ON evidence_purge_audit;
CREATE TRIGGER evidence_purge_audit_no_delete BEFORE DELETE ON evidence_purge_audit FOR EACH ROW EXECUTE FUNCTION dazl_guard_evidence_purge_audit_no_delete();

CREATE OR REPLACE FUNCTION dazl_guard_evidence_purge_audit_no_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (TRUE) THEN RAISE EXCEPTION 'purge audit is append-only'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_purge_audit_no_update ON evidence_purge_audit;
CREATE TRIGGER evidence_purge_audit_no_update BEFORE UPDATE ON evidence_purge_audit FOR EACH ROW EXECUTE FUNCTION dazl_guard_evidence_purge_audit_no_update();

CREATE OR REPLACE FUNCTION dazl_guard_lead_evidence_copies_delete_only_expired() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (OLD.expires_at > CAST(floor(extract(epoch from now())) AS BIGINT)
   AND NOT EXISTS (SELECT 1 FROM evidence_purge_gate g WHERE g.tenant_id = OLD.tenant_id)) THEN RAISE EXCEPTION 'evidence copy is still within its retention period'; END IF;
  RETURN OLD;
END $$;
DROP TRIGGER IF EXISTS lead_evidence_copies_delete_only_expired ON lead_evidence_copies;
CREATE TRIGGER lead_evidence_copies_delete_only_expired BEFORE DELETE ON lead_evidence_copies FOR EACH ROW EXECUTE FUNCTION dazl_guard_lead_evidence_copies_delete_only_expired();

CREATE OR REPLACE FUNCTION dazl_guard_lead_evidence_copies_no_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (TRUE) THEN RAISE EXCEPTION 'evidence copies are immutable'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS lead_evidence_copies_no_update ON lead_evidence_copies;
CREATE TRIGGER lead_evidence_copies_no_update BEFORE UPDATE ON lead_evidence_copies FOR EACH ROW EXECUTE FUNCTION dazl_guard_lead_evidence_copies_no_update();

CREATE OR REPLACE FUNCTION dazl_guard_leads_only_while_running() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF ((SELECT status FROM scan_jobs WHERE id = NEW.scan_job_id) IS DISTINCT FROM 'running') THEN RAISE EXCEPTION 'leads can only be added to a running job'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS leads_only_while_running ON leads;
CREATE TRIGGER leads_only_while_running BEFORE INSERT ON leads FOR EACH ROW EXECUTE FUNCTION dazl_guard_leads_only_while_running();

CREATE OR REPLACE FUNCTION dazl_guard_outreach_sent_is_final() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (OLD.status IN ('sent','skipped') AND NEW.status <> OLD.status) THEN RAISE EXCEPTION 'final outreach status'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS outreach_sent_is_final ON outreach_messages;
CREATE TRIGGER outreach_sent_is_final BEFORE UPDATE OF status ON outreach_messages FOR EACH ROW EXECUTE FUNCTION dazl_guard_outreach_sent_is_final();

CREATE OR REPLACE FUNCTION dazl_guard_scan_jobs_transitions() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (NOT (
      (OLD.status = 'pending' AND NEW.status = 'running') OR
      (OLD.status = 'running' AND NEW.status IN ('done','failed','pending')) OR
      OLD.status = NEW.status
    )) THEN RAISE EXCEPTION 'illegal scan job status transition'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS scan_jobs_transitions ON scan_jobs;
CREATE TRIGGER scan_jobs_transitions BEFORE UPDATE OF status ON scan_jobs FOR EACH ROW EXECUTE FUNCTION dazl_guard_scan_jobs_transitions();

CREATE OR REPLACE FUNCTION dazl_guard_sequence_sent_final() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (OLD.status = 'sent' AND (NEW.status <> 'sent' OR NEW.subject <> OLD.subject OR NEW.body <> OLD.body)) THEN RAISE EXCEPTION 'sent sequence step is final'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sequence_sent_final ON sequence_steps;
CREATE TRIGGER sequence_sent_final BEFORE UPDATE ON sequence_steps FOR EACH ROW EXECUTE FUNCTION dazl_guard_sequence_sent_final();
